<?php if($kind==='category'):?><label>Industry<input name="industry" maxlength="100" list="industries" required></label><?php elseif(in_array($kind,['subcategory','type','model'],true)):[$parent,$field]=['subcategory'=>['category','category_id'],'type'=>['subcategory','subcategory_id'],'model'=>['brand','brand_id']][$kind];?><label><?= e(ucfirst($parent)) ?><select name="<?= $field ?>" required><option value="">Choose parent</option><?php catalog_options($catalog[$parent]);?></select></label><?php endif;?>
<?php if($kind==='subcategory'):?><label>Artwork URL <small>Optional · HTTPS</small><input name="artwork_url" type="url" maxlength="500"></label><?php elseif($kind==='status'):?><label>Operational meaning<select name="operational_state"><option value="OPERATIONAL">Operational</option><option value="MAINTENANCE">Maintenance</option><option value="DOWN">Critical / Down</option></select></label><?php endif;?><button class="secondary">Add <?= e(strtolower($label)) ?></button></form><?php endforeach;?></div></details><?php endif;?>
