<details class="settings-form"><summary>Categories, types, manufacturers, models, and statuses</summary><?php foreach(['category','type','brand','model','status'] as $kind):?><h3><?= e(ucfirst($kind)) ?></h3><div class="directory-chips"><?php foreach($catalog[$kind] as $entry):?><span><?= e($entry['name']) ?><?php if($canEdit&&$entry['owner_id']):?> <a href="equipment-settings?kind=<?= $kind ?>&amp;edit=<?= e($entry['id']) ?>">Edit</a><?php endif;?></span><?php endforeach;?></div><?php endforeach;?></details></section>
